    {"id": "snc-m2", "docId": "snc-math-2020", "grade": 2, "subject": "math", "province": "pakistan", "units": [{"n": 1, "title": {"en": "Whole Numbers", "ur": "مکمل اعداد"}, "slo": [{"ref": "1.1", "t": "Write ordinal numbers from first to twentieth and write numbers 1 to 100 in words."}, {"ref": "1.2", "t": "Read and write numbers to 999 (the printed heading says up to 100, but the outcomes extend to 999); understand place value in 3-digit numbers; compare numbers; count backward and in tens and hundreds; order numbers; find largest and smallest; recognise 1,000 as the first 4-digit number."}]}, {"n": 2, "title": {"en": "Number Operations", "ur": "اعداد کے عمل"}, "slo": [{"ref": "2.1", "t": "Add 2-digit numbers with carrying; add mentally up to 50; solve real-life addition stories."}, {"ref": "2.2", "t": "Add 3-digit numbers to 1-, 2- and 3-digit numbers without carrying; solve related stories."}, {"ref": "2.3", "t": "Add 3-digit numbers with carrying of tens and hundreds; solve related stories."}, {"ref": "2.4", "t": "Subtract 2-digit numbers with borrowing; subtract mentally up to 50; solve related stories."}, {"ref": "2.5", "t": "Subtract 1-, 2- and 3-digit numbers from 3-digit numbers without borrowing; solve related stories."}, {"ref": "2.6", "t": "Subtract 3-digit numbers with borrowing; solve related stories; choose between addition and subtraction in mixed problems."}, {"ref": "2.7", "t": "Understand multiplication as repeated addition; use the multiplication sign; complete skip-counting sequences; learn tables of 2, 3, 4, 5 and 10 up to 10 x 10; solve one-digit stories."}, {"ref": "2.8", "t": "Use the division sign; understand division as repeated subtraction; divide within tables with zero remainder; solve one-digit division stories."}, {"ref": "2.9", "t": "Solve real-life problems with all four operations, including Pakistani currency, and justify the operation chosen."}]}, {"n": 3, "title": {"en": "Fractions", "ur": "کسریں"}, "slo": [{"ref": "3.1", "t": "Recognise equal parts of a whole; identify and write half, one-third and one-quarter; shade fractions; name unit fractions up to 1/10; recognise fractions such as 2/3 up to 9/10."}]}, {"n": 4, "title": {"en": "Measurement: Length, Mass and Capacity", "ur": "پیمائش: لمبائی، کمیت اور گنجائش"}, "slo": [{"ref": "4.1", "t": "Length: compare lengths, use metres and centimetres, measure with standard units, add and subtract within 100 in the same units."}, {"ref": "4.2", "t": "Mass: compare masses, use kilograms and grams, measure objects, add and subtract within 100 in the same units."}, {"ref": "4.3", "t": "Capacity: compare containers with non-standard units, use litres and millilitres, add and subtract within 100 in the same units."}]}, {"n": 5, "title": {"en": "Time", "ur": "وقت"}, "slo": [{"ref": "5.1", "t": "Know the hours in a day and minutes in an hour; read and write clock times in five-minute steps; use a.m. and p.m.; draw clock hands; use solar and Islamic calendars to find dates and days."}]}, {"n": 6, "title": {"en": "Geometry", "ur": "جیومیٹری"}, "slo": [{"ref": "6.1", "t": "Identify squares, rectangles, triangles, circles, semicircles and quarter-circles and their vertices and sides."}, {"ref": "6.2", "t": "Tell straight lines from curves, identify them in drawings, and draw a straight line of a given whole-number length with a ruler."}, {"ref": "6.3", "t": "Make or complete geometric patterns on a square grid by shape, size or orientation."}, {"ref": "6.4", "t": "Recognise and name cubes, cuboids, cylinders, cones and spheres."}]}]},
    {"id": "snc-m4", "docId": "snc-math-2020", "grade": 4, "subject": "math", "province": "pakistan", "units": [{"n": 1, "title": {"en": "Whole Numbers and Operations", "ur": "مکمل اعداد اور عمل"}, "slo": [{"ref": "1.1", "t": "Identify place values up to 100,000; read and write numbers in numerals and words; compare and order 5-digit numbers."}, {"ref": "1.2", "t": "Add numbers up to 5 digits and solve real-life addition problems."}, {"ref": "1.3", "t": "Subtract numbers up to 5 digits and solve real-life subtraction problems."}, {"ref": "1.4", "t": "Multiply numbers up to 4 digits by numbers up to 2 digits and solve related real-life problems."}, {"ref": "1.5", "t": "Divide numbers up to 4 digits by numbers up to 2 digits and choose the right operation for real-life problems."}, {"ref": "1.6", "t": "Identify increasing and decreasing patterns and their rules, describe patterns in tables or charts, and complete number sequences."}]}, {"n": 2, "title": {"en": "Factors and Multiples", "ur": "اجزائے ضربی اور ضعاف"}, "slo": [{"ref": "2.1", "t": "Apply divisibility rules for 2, 3, 5 and 10 to numbers up to 5 digits."}, {"ref": "2.2", "t": "Identify and tell apart 2-digit prime and composite numbers."}, {"ref": "2.3", "t": "Find factors of numbers up to 50, list the first ten multiples of a 1-digit number, and tell factors from multiples."}, {"ref": "2.4", "t": "Factorise numbers into prime factors, identify primes below 100, and find common factors and common multiples of 2-digit numbers (the printed layout of this sub-unit is not fully clear)."}]}, {"n": 3, "title": {"en": "Fractions", "ur": "کسریں"}, "slo": [{"ref": "3.1", "t": "Recognise like and unlike fractions, compare unlike fractions using equivalent fractions, and simplify fractions to lowest terms."}, {"ref": "3.2", "t": "Identify unit, proper and improper fractions and mixed numbers, convert between improper fractions and mixed numbers, and order fractions."}, {"ref": "3.3", "t": "Add and subtract fractions with like denominators."}, {"ref": "3.4", "t": "Multiply proper, improper and mixed fractions by whole numbers, and multiply two such fractions or mixed numbers."}, {"ref": "3.5", "t": "Divide fractions and mixed numbers by whole numbers, and choose the right operation in real-life situations."}]}, {"n": 4, "title": {"en": "Decimals", "ur": "اعشاریہ"}, "slo": [{"ref": "4.1", "t": "Understand decimals as another way to write fractions, express them with denominators of 10, 100 or 1000, and identify place values up to 3 decimal places."}, {"ref": "4.2", "t": "Convert fractions to decimals when the denominator is or can be made 10, 100 or 1000, and convert decimals up to 3 places to fractions."}, {"ref": "4.3", "t": "Add and subtract decimals, multiply and divide decimals by whole numbers and by 10, 100 or 1000, and solve real-life problems."}, {"ref": "4.4", "t": "Round whole numbers to the nearest 10, 100 or 1000, round decimals to the nearest whole number, and estimate sums, differences and quotients."}]}, {"n": 5, "title": {"en": "Measurements", "ur": "پیمائش"}, "slo": [{"ref": "5.1", "t": "Use metric units of length, convert between km, m, cm and mm, and add and subtract lengths in the same units."}, {"ref": "5.2", "t": "Use metric units of mass, convert between kg, g and mg, and add and subtract masses in the same units."}, {"ref": "5.3", "t": "Use metric units of capacity, convert litres to millilitres, add and subtract capacities, and solve real-life problems."}, {"ref": "5.4", "t": "Read and write time on 12- and 24-hour clocks, convert between time units including years, months, weeks and days, and add and subtract time without carrying or borrowing."}]}, {"n": 6, "title": {"en": "Geometry", "ur": "جیومیٹری"}, "slo": [{"ref": "6.1", "t": "Identify parallel and non-parallel lines."}, {"ref": "6.2", "t": "Form angles from intersecting rays, measure and draw angles in degrees with a protractor, tell acute, obtuse and right angles apart, and find right angles in 2-D shapes."}, {"ref": "6.3", "t": "Describe the radius, diameter and circumference of a circle."}, {"ref": "6.4", "t": "Find the perimeter and area of 2-D figures on a square grid and recognise the units used."}, {"ref": "6.5", "t": "Recognise lines of symmetry in 2-D shapes and complete symmetric figures on grids or dot patterns."}, {"ref": "6.6", "t": "Compare and sort 3-D objects such as cubes, cuboids, pyramids, cylinders, cones and spheres."}]}, {"n": 7, "title": {"en": "Data Handling", "ur": "معلومات کی ترتیب"}, "slo": [{"ref": "7.1", "t": "Read simple horizontal and vertical bar graphs and interpret real-life data in them."}, {"ref": "7.2", "t": "Read line graphs and interpret real-life data in them."}, {"ref": "7.3", "t": "Read pie charts and interpret real-life data in them."}]}]},
    {"id": "snc-m5", "docId": "snc-math-2020", "grade": 5, "subject": "math", "province": "pakistan", "units": [{"n": 1, "title": {"en": "Whole Numbers and Operations", "ur": "مکمل اعداد اور عمل"}, "slo": [{"ref": "1.1", "t": "Read and write numbers up to 1,000,000 in numerals and words."}, {"ref": "1.2", "t": "Add and subtract numbers up to 6 digits."}, {"ref": "1.3", "t": "Multiply and divide numbers up to 5 digits by 10, 100, 1000 and by 2- or 3-digit numbers; solve real-life problems with all four operations."}, {"ref": "1.4", "t": "Find missing terms using a pattern rule, extend increasing and decreasing patterns, and describe patterns in tables or charts."}]}, {"n": 2, "title": {"en": "HCF and LCM", "ur": "عاد اعظم اور ذوالاضعاف اقل"}, "slo": [{"ref": "2.1", "t": "Find the highest common factor of two or three 2-digit numbers using prime factorisation and division."}, {"ref": "2.2", "t": "Find the least common multiple of two or three 2-digit numbers in the same ways and solve real-life HCF and LCM problems."}]}, {"n": 3, "title": {"en": "Fractions", "ur": "کسریں"}, "slo": [{"ref": "3.1", "t": "Add and subtract two or three fractions with different denominators."}, {"ref": "3.2", "t": "Multiply a fraction by a whole number using diagrams, and multiply two or three proper, improper or mixed fractions; solve real-life problems."}, {"ref": "3.3", "t": "Divide one fraction by another, including mixed numbers, and solve real-life problems."}]}, {"n": 4, "title": {"en": "Decimal Numbers and Percentages", "ur": "اعشاری اعداد اور فیصد"}, "slo": [{"ref": "4.1", "t": "Compare, order, add, subtract, multiply and divide decimals; convert fractions to decimals; solve real-life problems."}, {"ref": "4.2", "t": "Round numbers to the nearest tenth or hundredth and estimate sums and differences."}, {"ref": "4.3", "t": "Treat percentages as fractions, convert between percentages, fractions and decimals, and solve real-life problems."}]}, {"n": 5, "title": {"en": "Distance and Time", "ur": "فاصلہ اور وقت"}, "slo": [{"ref": "5.1", "t": "Convert between kilometres, metres, centimetres and millimetres and solve real-life problems."}, {"ref": "5.2", "t": "Convert between hours, minutes, seconds, years, months, days and weeks; add and subtract time intervals; solve real-life problems."}]}, {"n": 6, "title": {"en": "Unitary Method", "ur": "اکائی طریقہ"}, "slo": [{"ref": "6.1", "t": "Find the value of many items from the value of one, or of one item from the value of many."}]}, {"n": 7, "title": {"en": "Geometry", "ur": "جیومیٹری"}, "slo": [{"ref": "7.1", "t": "Recognise straight and reflex angles, understand the degree as the unit of angle, estimate and classify angles, construct angles with a protractor, and describe adjacent, complementary and supplementary angles."}, {"ref": "7.2", "t": "Triangles: the source text could not be read past the start of this sub-unit, so its outcomes are not available here."}]}], "partial": true}
